CREATE TABLE IF NOT EXISTS appstore_idempotency_key (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  organization_id TEXT NOT NULL DEFAULT '0',
  scope TEXT NOT NULL,
