-- folded migration: migrations/postgres/0002_appstore_platform_evolution.up.sql
-- sdkwork:migration
-- id: 0002_appstore_platform_evolution
-- engine: postgres
-- module: sdkwork-appstore
-- purpose: Make distribution platform a first-class entity aligned with App
--   Store Connect / Google Play / Microsoft Store / AppGallery / browser
--   extension stores / mini program platforms: platform dictionary, per-app
--   platform packages, per-platform release tracks with force-update and
--   kill-switch, signing credential registry, review lifecycle, regional
--   pricing, promo codes, tester groups, search read model, and unified
--   analytics. Also reconciles baseline counter widths and library uniqueness
--   for pre-fold environments (idempotent; see Part 1 notes).
-- reversible: false
-- rollback: forward-fix (all changes are additive; rollback is achieved by
--   not consuming the new columns/tables, no data is dropped)
-- transactional: true
-- lock: lightweight
-- lock_timeout: 2s
-- statement_timeout: 60s

BEGIN;

-- 0002_appstore_platform_evolution.up.sql
-- SDKWork App Store platform-alignment evolution
-- Domain: appstore | Prefix: appstore_ | Compliance: L2 (L3 tables noted)
-- Baseline: folds after 0001_appstore_baseline.sql
--
-- Goals:
--   1. Fix known structural defects in the baseline schema (P0 type bugs, counter widths, library uniqueness scope).
--   2. Make distribution platform a first-class entity so the catalog covers
--      iOS/iPadOS/Android/HarmonyOS mobile apps, Windows/macOS/Linux desktop apps,
--      PC-browser web apps and browser extensions, and multi-platform mini programs,
--      aligned with App Store Connect / Google Play / Microsoft Store / AppGallery /
--      Chrome Web Store / WeChat & Alipay mini program platform capabilities.
--   3. Add industry-standard store capabilities: per-platform release tracks with
--      force-update/kill-switch, signing credential registry, full review lifecycle,
--      regional pricing, promo codes, beta tester groups, search read model, and a
--      unified daily analytics metric table.
--
-- All changes are expand-only. No existing column is dropped or renamed in this migration.
-- JSON columns in NEW tables use native JSONB (declared in specs/database/schema-registry.yaml);
-- legacy TEXT-JSON columns in existing tables are left untouched for compatibility.

-- ---------------------------------------------------------------------------
-- Part 1 — Structural defect fixes (superseded by the folded baseline)
-- ---------------------------------------------------------------------------
-- The original 0002 carried five defect fixes. They are now folded directly
-- into database/ddl/baseline/postgres/0001_appstore_baseline.sql:
--   * FIX-1 (package_format TEXT)        -> folded; CREATE TABLE declares TEXT.
--   * FIX-2 (version_code_numeric)       -> withdrawn entirely; the column had
--     no repository readers or writers and its index could never order fresh
--     inserts. Update checks order by published_at instead.
--   * FIX-3 (rating averages NUMERIC)    -> withdrawn; it broke the PostgreSQL
--     runtime because repository rows/bindings are String end to end. Averages
--     stay TEXT in both engines; aggregation happens on INTEGER rating columns.
--   * FIX-4 / FIX-5 remain below as idempotent reconciliation statements.
-- ---------------------------------------------------------------------------

-- FIX-4 (P1): hot-row counters as INTEGER will overflow at scale (App Store /
-- Play scale catalogs). Widen to BIGINT. Idempotent: columns are already
-- BIGINT in the folded baseline.
ALTER TABLE appstore_app ALTER COLUMN download_count TYPE BIGINT;
ALTER TABLE appstore_listing ALTER COLUMN download_count TYPE BIGINT;
ALTER TABLE appstore_listing_metric_snapshot
  ALTER COLUMN impression_count TYPE BIGINT,
  ALTER COLUMN detail_view_count TYPE BIGINT,
  ALTER COLUMN install_count TYPE BIGINT,
  ALTER COLUMN uninstall_count TYPE BIGINT,
  ALTER COLUMN update_count TYPE BIGINT;

-- FIX-5 (P1): appstore_user_library_item uniqueness was scoped to
-- (user, app_key, platform), which collides when one app has multiple
-- listings (regional/alt storefronts). Scope to listing identity instead.
-- The folded baseline already declares this constraint inline; the guard
-- keeps the migration replayable on both old and fresh databases.
ALTER TABLE appstore_user_library_item
  DROP CONSTRAINT IF EXISTS appstore_user_library_item_tenant_id_user_id_app_key_platform_key;
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'appstore_user_library_item_uk'
      AND conrelid = 'appstore_user_library_item'::regclass
  ) THEN
    ALTER TABLE appstore_user_library_item
      ADD CONSTRAINT appstore_user_library_item_uk
      UNIQUE (tenant_id, user_id, listing_id, platform);
  END IF;
END $$;

-- ---------------------------------------------------------------------------
-- Part 2 — Platform as first-class entity
-- ---------------------------------------------------------------------------

-- Platform reference dictionary. Seeds: database/seeds/common/011_platform_dictionary.sql
-- Families: mobile | desktop | web | browser-extension | miniprogram
CREATE TABLE IF NOT EXISTS appstore_platform_dictionary (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL DEFAULT '0',
  platform_code TEXT NOT NULL,
  platform_family TEXT NOT NULL,
  os_vendor TEXT NOT NULL,
  package_formats JSONB NOT NULL DEFAULT '[]',
  identity_field TEXT NOT NULL,
  requires_store_review INTEGER NOT NULL DEFAULT 1,
  platform_status TEXT NOT NULL DEFAULT 'active',
  sort_order INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, platform_code)
);

-- Per-platform package identity for an app: iOS bundleId, Android packageName,
-- HarmonyOS bundleName, Windows MSIX identity, browser extension id,
-- mini program appid, PWA start_url scope, etc.
CREATE TABLE IF NOT EXISTS appstore_app_platform (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  organization_id TEXT NOT NULL DEFAULT '0',
  app_id TEXT NOT NULL,
  platform_code TEXT NOT NULL,
  platform_status TEXT NOT NULL DEFAULT 'draft',
  package_identity TEXT NOT NULL,
  external_store_app_id TEXT,
  min_os_version TEXT,
  target_os_version TEXT,
  supported_architectures JSONB NOT NULL DEFAULT '[]',
  device_families JSONB NOT NULL DEFAULT '[]',
  compatibility_json JSONB NOT NULL DEFAULT '{}',
  distribution_mode TEXT NOT NULL DEFAULT 'store',
  config_json JSONB NOT NULL DEFAULT '{}',
  version INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, app_id, platform_code),
  UNIQUE (tenant_id, platform_code, package_identity)
);
CREATE INDEX IF NOT EXISTS idx_appstore_app_platform_app
  ON appstore_app_platform (tenant_id, app_id, platform_status);

-- Per-platform release track (App Store platform version / Play release /
-- mini program release). The listing-level appstore_release remains the
-- storefront concept; platform_release is the distribution authority per OS.
CREATE TABLE IF NOT EXISTS appstore_platform_release (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  organization_id TEXT NOT NULL DEFAULT '0',
  app_platform_id TEXT NOT NULL,
  channel_id TEXT NOT NULL,
  release_no TEXT NOT NULL,
  version_name TEXT NOT NULL,
  version_code BIGINT NOT NULL,
  release_status TEXT NOT NULL,
  release_phase TEXT NOT NULL DEFAULT 'production',
  force_update_flag INTEGER NOT NULL DEFAULT 0,
  min_supported_version_code BIGINT,
  kill_switch_flag INTEGER NOT NULL DEFAULT 0,
  manifest_snapshot_json JSONB NOT NULL DEFAULT '{}',
  submitted_at TIMESTAMPTZ,
  approved_at TIMESTAMPTZ,
  published_at TIMESTAMPTZ,
  retired_at TIMESTAMPTZ,
  version INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, release_no),
  UNIQUE (tenant_id, app_platform_id, channel_id, version_code)
);
CREATE INDEX IF NOT EXISTS idx_appstore_platform_release_update_check
  ON appstore_platform_release (tenant_id, app_platform_id, release_status, version_code DESC);

-- Artifacts may now bind to a platform track and carry supply-chain metadata
-- (delta patches, signing scheme, malware scan state, CDN location).
ALTER TABLE appstore_release_artifact
  ADD COLUMN IF NOT EXISTS app_platform_id TEXT,
  ADD COLUMN IF NOT EXISTS platform_release_id TEXT,
  ADD COLUMN IF NOT EXISTS artifact_kind TEXT NOT NULL DEFAULT 'full',
  ADD COLUMN IF NOT EXISTS delta_base_version_code BIGINT,
  ADD COLUMN IF NOT EXISTS signature_scheme TEXT,
  ADD COLUMN IF NOT EXISTS signing_cert_fingerprint TEXT,
  ADD COLUMN IF NOT EXISTS virus_scan_status TEXT NOT NULL DEFAULT 'pending',
  ADD COLUMN IF NOT EXISTS virus_scan_vendor TEXT,
  ADD COLUMN IF NOT EXISTS virus_scan_completed_at TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS cdn_url TEXT;
CREATE INDEX IF NOT EXISTS idx_appstore_release_artifact_platform_release
  ON appstore_release_artifact (tenant_id, platform_release_id, artifact_status);

-- Publisher signing credential registry (App Store signing / Play App Signing /
-- Windows EV code signing / HarmonyOS release cert). Enables upgrade-signature
-- consistency checks and anti-repackaging verification.
CREATE TABLE IF NOT EXISTS appstore_signing_credential (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  organization_id TEXT NOT NULL DEFAULT '0',
  publisher_id TEXT NOT NULL,
  app_id TEXT,
  platform_code TEXT NOT NULL,
  credential_type TEXT NOT NULL,
  fingerprint_sha256 TEXT NOT NULL,
  certificate_subject TEXT,
  valid_from TIMESTAMPTZ,
  valid_until TIMESTAMPTZ,
  credential_status TEXT NOT NULL,
  rotated_from_credential_id TEXT,
  evidence_media_resource_id TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, fingerprint_sha256)
);
CREATE INDEX IF NOT EXISTS idx_appstore_signing_credential_publisher
  ON appstore_signing_credential (tenant_id, publisher_id, platform_code, credential_status);

-- ---------------------------------------------------------------------------
-- Part 3 — Reviews and ratings aligned with App Store / Play review lifecycle
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS appstore_listing_review (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  organization_id TEXT NOT NULL DEFAULT '0',
  listing_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  release_id TEXT,
  platform_code TEXT,
  rating INTEGER NOT NULL CHECK (rating BETWEEN 1 AND 5),
  title TEXT,
  review_body TEXT NOT NULL DEFAULT '',
  locale TEXT,
  review_status TEXT NOT NULL DEFAULT 'published',
  developer_reply TEXT,
  developer_user_id TEXT,
  developer_reply_at TIMESTAMPTZ,
  helpful_count INTEGER NOT NULL DEFAULT 0,
  report_count INTEGER NOT NULL DEFAULT 0,
  edited_at TIMESTAMPTZ,
  deleted_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, listing_id, user_id)
);
CREATE INDEX IF NOT EXISTS idx_appstore_listing_review_listing
  ON appstore_listing_review (tenant_id, listing_id, review_status, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_appstore_listing_review_release
  ON appstore_listing_review (tenant_id, release_id, created_at DESC);

CREATE TABLE IF NOT EXISTS appstore_listing_review_vote (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  review_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  vote_value INTEGER NOT NULL DEFAULT 1,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, review_id, user_id)
);

CREATE TABLE IF NOT EXISTS appstore_listing_review_report (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  review_id TEXT NOT NULL,
  reporter_user_id TEXT NOT NULL,
  report_reason_code TEXT NOT NULL,
  report_note TEXT,
  report_status TEXT NOT NULL DEFAULT 'open',
  handled_by TEXT,
  handled_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, review_id, reporter_user_id)
);
CREATE INDEX IF NOT EXISTS idx_appstore_listing_review_report_status
  ON appstore_listing_review_report (tenant_id, report_status, created_at ASC);

-- Star distribution snapshot (1..5) per listing per day, as surfaced on
-- App Store / Play product pages.
CREATE TABLE IF NOT EXISTS appstore_rating_distribution_snapshot (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  listing_id TEXT NOT NULL,
  snapshot_date TEXT NOT NULL,
  star_1_count INTEGER NOT NULL DEFAULT 0,
  star_2_count INTEGER NOT NULL DEFAULT 0,
  star_3_count INTEGER NOT NULL DEFAULT 0,
  star_4_count INTEGER NOT NULL DEFAULT 0,
  star_5_count INTEGER NOT NULL DEFAULT 0,
  rating_avg NUMERIC(4,2),
  rating_count INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, listing_id, snapshot_date)
);

-- ---------------------------------------------------------------------------
-- Part 4 — Regional pricing and promo codes (catalog/display side; checkout
-- and ledger remain commerce-domain owned)
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS appstore_listing_price (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  organization_id TEXT NOT NULL DEFAULT '0',
  listing_id TEXT NOT NULL,
  region_code TEXT NOT NULL DEFAULT 'GLOBAL',
  currency_code TEXT NOT NULL,
  price_amount NUMERIC(12,2) NOT NULL DEFAULT 0,
  price_tier_code TEXT,
  pricing_mode TEXT NOT NULL DEFAULT 'free',
  starts_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  ends_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, listing_id, region_code, starts_at)
);
CREATE INDEX IF NOT EXISTS idx_appstore_listing_price_lookup
  ON appstore_listing_price (tenant_id, listing_id, region_code, starts_at DESC);

CREATE TABLE IF NOT EXISTS appstore_promo_code_batch (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  organization_id TEXT NOT NULL DEFAULT '0',
  listing_id TEXT NOT NULL,
  release_id TEXT,
  batch_no TEXT NOT NULL,
  purpose TEXT NOT NULL DEFAULT 'promotional',
  total_count INTEGER NOT NULL DEFAULT 0,
  redeemed_count INTEGER NOT NULL DEFAULT 0,
  starts_at TIMESTAMPTZ,
  expires_at TIMESTAMPTZ,
  batch_status TEXT NOT NULL DEFAULT 'active',
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, batch_no)
);

CREATE TABLE IF NOT EXISTS appstore_promo_code (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  batch_id TEXT NOT NULL,
  listing_id TEXT NOT NULL,
  code_hash TEXT NOT NULL,
  code_hint TEXT,
  code_status TEXT NOT NULL DEFAULT 'active',
  redeemed_by TEXT,
  redeemed_at TIMESTAMPTZ,
  expires_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, code_hash)
);
CREATE INDEX IF NOT EXISTS idx_appstore_promo_code_batch
  ON appstore_promo_code (tenant_id, batch_id, code_status);

-- ---------------------------------------------------------------------------
-- Part 5 — Beta tester groups (TestFlight-style internal/external groups)
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS appstore_release_tester_group (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  organization_id TEXT NOT NULL DEFAULT '0',
  app_id TEXT NOT NULL,
  group_no TEXT NOT NULL,
  group_name TEXT NOT NULL,
  group_type TEXT NOT NULL DEFAULT 'external',
  group_status TEXT NOT NULL DEFAULT 'active',
  max_testers INTEGER,
  created_by TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, group_no)
);

CREATE TABLE IF NOT EXISTS appstore_release_tester_group_member (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  group_id TEXT NOT NULL,
  user_id TEXT,
  contact_email TEXT NOT NULL,
  member_status TEXT NOT NULL DEFAULT 'invited',
  added_by TEXT,
  added_at TIMESTAMPTZ,
  removed_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, group_id, contact_email)
);
CREATE INDEX IF NOT EXISTS idx_appstore_release_tester_group_member_group
  ON appstore_release_tester_group_member (tenant_id, group_id, member_status);

ALTER TABLE appstore_release_beta_invite ADD COLUMN IF NOT EXISTS tester_group_id TEXT;

-- ---------------------------------------------------------------------------
-- Part 6 — Search read model and unified analytics metrics
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS appstore_catalog_search_doc (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  listing_id TEXT NOT NULL,
  locale TEXT NOT NULL,
  display_name TEXT NOT NULL,
  subtitle TEXT,
  keywords TEXT NOT NULL DEFAULT '',
  short_description TEXT,
  platform_codes TEXT NOT NULL DEFAULT '[]',
  popularity_score NUMERIC(12,4) NOT NULL DEFAULT 0,
  doc_status TEXT NOT NULL DEFAULT 'active',
  indexed_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, listing_id, locale)
);
CREATE INDEX IF NOT EXISTS idx_appstore_catalog_search_doc_lookup
  ON appstore_catalog_search_doc (tenant_id, locale, doc_status, popularity_score DESC);

-- Unified daily metric store (subject-scoped, platform/region sliced).
-- metric_code examples: impression, detail_view, install, uninstall, update,
-- crash_free_sessions, anr_rate, rating_count, listing_revenue_display.
CREATE TABLE IF NOT EXISTS appstore_analytics_metric_daily (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  subject_type TEXT NOT NULL,
  subject_id TEXT NOT NULL,
  metric_code TEXT NOT NULL,
  platform_code TEXT NOT NULL DEFAULT 'ALL',
  region_code TEXT NOT NULL DEFAULT 'GLOBAL',
  metric_value NUMERIC(18,4) NOT NULL DEFAULT 0,
  snapshot_date TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, subject_type, subject_id, metric_code, platform_code, region_code, snapshot_date)
);
CREATE INDEX IF NOT EXISTS idx_appstore_analytics_metric_daily_subject
  ON appstore_analytics_metric_daily (tenant_id, subject_type, subject_id, snapshot_date DESC);
COMMIT;

-- folded migration: migrations/postgres/0003_user_store.up.sql
-- sdkwork:migration
-- id: 0003_user_store
-- engine: postgres
-- module: sdkwork-appstore
-- purpose: User-owned custom categories and shareable personal appstore
--   views (capability: userStore). Three new tables: appstore_user_category
--   (user-defined categories, isolated from platform catalog categories),
--   appstore_user_category_item (category-to-listing bindings, storing
--   listing_id references only; display cards resolve through the listing
--   domain via a port, never by cross-domain joins), and
--   appstore_user_store_share (immutable-token public share views scoped to
--   all or selected categories with visibility, expiry, and revoke state).
-- reversible: true
-- rollback: DROP TABLE IF EXISTS appstore_user_store_share;
--   DROP TABLE IF EXISTS appstore_user_category_item;
--   DROP TABLE IF EXISTS appstore_user_category;
-- transactional: true
-- lock: lightweight
-- lock_timeout: 2s
-- statement_timeout: 30s

BEGIN;

CREATE TABLE IF NOT EXISTS appstore_user_category (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  organization_id TEXT NOT NULL DEFAULT '0',
  owner_user_id TEXT NOT NULL,
  name TEXT NOT NULL,
  description TEXT,
  icon_media_resource_id TEXT,
  sort_order INTEGER NOT NULL DEFAULT 0,
  category_status TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL,
  UNIQUE (tenant_id, owner_user_id, name)
);

CREATE INDEX IF NOT EXISTS idx_appstore_user_category_owner
  ON appstore_user_category (tenant_id, owner_user_id, category_status, sort_order);

CREATE TABLE IF NOT EXISTS appstore_user_category_item (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  organization_id TEXT NOT NULL DEFAULT '0',
  user_category_id TEXT NOT NULL,
  listing_id TEXT NOT NULL,
  note TEXT,
  sort_order INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL,
  UNIQUE (user_category_id, listing_id)
);

CREATE INDEX IF NOT EXISTS idx_appstore_user_category_item_category
  ON appstore_user_category_item (tenant_id, user_category_id, sort_order);

CREATE INDEX IF NOT EXISTS idx_appstore_user_category_item_listing
  ON appstore_user_category_item (tenant_id, listing_id);

CREATE TABLE IF NOT EXISTS appstore_user_store_share (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  organization_id TEXT NOT NULL DEFAULT '0',
  owner_user_id TEXT NOT NULL,
  share_token TEXT NOT NULL,
  title TEXT NOT NULL,
  description TEXT,
  share_scope TEXT NOT NULL,
  selected_category_ids_json TEXT NOT NULL DEFAULT '[]',
  share_visibility TEXT NOT NULL,
  share_status TEXT NOT NULL,
  expires_at TIMESTAMPTZ,
  view_count BIGINT NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_appstore_user_store_share_token
  ON appstore_user_store_share (share_token);

CREATE INDEX IF NOT EXISTS idx_appstore_user_store_share_owner
  ON appstore_user_store_share (tenant_id, owner_user_id, share_status);

COMMIT;

-- folded migration: migrations/postgres/0004_appstore_app_sku_and_deployment_binding.up.sql
-- sdkwork:migration
-- id: 0004_appstore_app_sku_and_deployment_binding
-- engine: postgres
-- module: sdkwork-appstore
-- purpose: Add the application specification (SKU) layer and the deployment
--   binding layer.
--
--   Application specification layer. An appstore application is authored by
--   several people at once and ships as several independently describable,
--   independently deliverable variants. `appstore_app_sku` is that variant
--   entity, modelled as an SKU: `sku_code` is the stable identity of the
--   variant and the version number is one of its attributes
--   (`version_name` + `version_code`) rather than the identity itself.
--
--   `version` is NOT part of the table or entity name on purpose. Inside this
--   module the token already carries three distinct meanings --
--   `DATABASE_SPEC.md` section 6.6 optimistic locking (`version BIGINT`),
--   release version numbers (`appstore_release.version_name/_code`), and
--   platform release version numbers
--   (`appstore_platform_release.version_name/_code`). Naming the entity
--   `appstore_app_version` would collide with all three, which is the
--   second-order ambiguity `NAMING_SPEC.md` section 0.2 exists to prevent.
--
--   Specification to version cardinality is 1:N: one `version_code` may carry
--   several SKUs distinguished by `sku_code` (for example a standard and a
--   professional variant of 1.2.0), so `version_code` is indexed but not
--   unique. Uniqueness is anchored on `sku_code`.
--
--   Per-SKU development provenance. Each SKU records which coding agent
--   produced it (`development_tool`), which model implemented it
--   (`development_model` + `model_provider`), and who owns it
--   (`primary_owner_user_id`). A SKU may be implemented by more than one model,
--   so `appstore_app_sku_model` carries the model bindings with an
--   implementation role and weight, while `appstore_app_sku_attribute` carries
--   open-ended SKU attributes grouped by axis. Contributors are recorded in
--   `appstore_app_sku_contributor` so concurrent development is attributable.
--
--   Display default. `appstore_app_sku.is_default` marks the SKU a storefront
--   shows by default. "Default version" is a derived view of that flag (the
--   `version_code` of the default SKU), which keeps a single source of truth
--   rather than a second default column that can disagree with it. Both default
--   flags are enforced by partial unique indexes so a concurrent double-write
--   cannot produce two defaults.
--
--   Deployment binding layer. `appstore_app_deployment_binding` links an
--   appstore application, and optionally one of its SKUs, to the deployment
--   owned `deploy_app` / `deploy_deployment` rows. Deployment is a separate
--   module, so the binding stores the external snowflake ids plus display
--   snapshots and a configuration snapshot, and integrity is verified through
--   the deployments SDK rather than by a cross-module foreign key. Bindings
--   may be application level (`app_sku_id IS NULL`) or SKU level.
--
--   `appstore_app.default_sku_id` and `appstore_app.default_deployment_binding_id`
--   denormalize the two resolved defaults for list and detail reads; the partial
--   unique indexes above remain the authority. `appstore_release.app_sku_id` and
--   `appstore_platform_release.app_sku_id` attach published artifacts to the SKU
--   they ship, which the 1:N specification cardinality requires.
--
-- reversible: false
-- rollback: forward-fix (every statement is additive: new tables and nullable
--   columns only, no column is dropped, renamed or retyped, and no existing row
--   is rewritten. Reversal is achieved by not consuming the new tables and
--   columns; dropping them would discard specification and binding data and is
--   therefore not offered as a down migration)
-- transactional: true
-- lock: lightweight
-- lock_timeout: 2s
-- statement_timeout: 60s
-- contract_version: 1.1.0

BEGIN;

-- ---------------------------------------------------------------------------
-- Part 1 — Application specification (SKU) entity
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS appstore_app_sku (
  id BIGINT NOT NULL PRIMARY KEY,
  uuid VARCHAR(64) NOT NULL,
  tenant_id BIGINT NOT NULL,
  organization_id BIGINT NOT NULL DEFAULT 0,
  app_id TEXT NOT NULL,
  sku_code VARCHAR(64) NOT NULL,
  sku_kind VARCHAR(32) NOT NULL DEFAULT 'release',
  sku_status VARCHAR(24) NOT NULL DEFAULT 'draft',
  is_default BOOLEAN NOT NULL DEFAULT FALSE,
  display_priority INTEGER NOT NULL DEFAULT 0,
  version_name VARCHAR(64) NOT NULL,
  version_code BIGINT NOT NULL,
  development_tool VARCHAR(64),
  development_model VARCHAR(128),
  model_provider VARCHAR(64),
  primary_owner_user_id BIGINT,
  git_ref VARCHAR(255),
  source_template_id BIGINT,
  source_template_version_id BIGINT,
  manifest_snapshot_json JSONB NOT NULL DEFAULT '{}'::jsonb,
  attribute_summary JSONB NOT NULL DEFAULT '{}'::jsonb,
  metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
  data_scope INTEGER NOT NULL DEFAULT 0,
  status INTEGER NOT NULL DEFAULT 1,
  version BIGINT NOT NULL DEFAULT 0,
  activated_at TIMESTAMPTZ,
  defaulted_at TIMESTAMPTZ,
  deprecated_at TIMESTAMPTZ,
  retired_at TIMESTAMPTZ,
  deleted_at TIMESTAMPTZ,
  created_by BIGINT,
  updated_by BIGINT,
  deleted_by BIGINT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT uk_appstore_app_sku_uuid UNIQUE (uuid),
  CONSTRAINT chk_appstore_app_sku_kind
    CHECK (sku_kind IN ('release', 'beta', 'canary', 'edition', 'custom')),
  CONSTRAINT chk_appstore_app_sku_status
    CHECK (
      sku_status IN (
        'draft',
        'pending_review',
        'approved',
        'published',
        'deprecated',
        'retired'
      )
    ),
  CONSTRAINT chk_appstore_app_sku_version_code CHECK (version_code >= 0),
  CONSTRAINT chk_appstore_app_sku_display_priority CHECK (display_priority >= 0)
);

-- `sku_code` is the stable identity of one specification. Uniqueness is scoped
-- to live rows so a retired SKU's code can be reused, per `DATABASE_SPEC.md`
-- section 6.6 which requires soft-delete tables to define how uniqueness
-- behaves for deleted rows.
CREATE UNIQUE INDEX IF NOT EXISTS uq_appstore_app_sku_code
  ON appstore_app_sku (tenant_id, app_id, sku_code)
  WHERE deleted_at IS NULL;

-- Single default specification per application. Partial unique indexes are the
-- authority for both default flags in this migration; application code must not
-- treat the denormalized `appstore_app.default_sku_id` as the guarantee.
CREATE UNIQUE INDEX IF NOT EXISTS uq_appstore_app_sku_default
  ON appstore_app_sku (tenant_id, app_id)
  WHERE is_default AND deleted_at IS NULL;

-- Storefront specification list: equality on tenant/app/status, ordered by
-- display priority then descending version, with `id` as the keyset tie-breaker
-- (`DATABASE_SPEC.md` section 10).
CREATE INDEX IF NOT EXISTS idx_appstore_app_sku_list
  ON appstore_app_sku (tenant_id, app_id, sku_status, display_priority, version_code DESC, id);

-- Specifications of one version, and 1:N version roll-ups.
CREATE INDEX IF NOT EXISTS idx_appstore_app_sku_version
  ON appstore_app_sku (tenant_id, app_id, version_code);

CREATE INDEX IF NOT EXISTS idx_appstore_app_sku_owner
  ON appstore_app_sku (tenant_id, primary_owner_user_id)
  WHERE primary_owner_user_id IS NOT NULL;

-- Development provenance lookup: which specifications were produced by a tool
-- or implemented by a model. Serves coverage reporting, not a hot read path.
CREATE INDEX IF NOT EXISTS idx_appstore_app_sku_provenance
  ON appstore_app_sku (tenant_id, development_tool, development_model)
  WHERE development_tool IS NOT NULL OR development_model IS NOT NULL;

-- ---------------------------------------------------------------------------
-- Part 2 — Specification attributes (open-ended SKU attribute axis)
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS appstore_app_sku_attribute (
  id BIGINT NOT NULL PRIMARY KEY,
  uuid VARCHAR(64) NOT NULL,
  tenant_id BIGINT NOT NULL,
  organization_id BIGINT NOT NULL DEFAULT 0,
  app_sku_id BIGINT NOT NULL,
  attribute_group VARCHAR(64) NOT NULL,
  attribute_key VARCHAR(128) NOT NULL,
  attribute_value TEXT,
  value_type VARCHAR(24) NOT NULL DEFAULT 'string',
  enum_code VARCHAR(128),
  unit VARCHAR(32),
  locale VARCHAR(16) NOT NULL DEFAULT '',
  is_public BOOLEAN NOT NULL DEFAULT TRUE,
  sort_weight INTEGER NOT NULL DEFAULT 0,
  metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
  status INTEGER NOT NULL DEFAULT 1,
  version BIGINT NOT NULL DEFAULT 0,
  deleted_at TIMESTAMPTZ,
  created_by BIGINT,
  updated_by BIGINT,
  deleted_by BIGINT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT uk_appstore_app_sku_attribute_uuid UNIQUE (uuid),
  CONSTRAINT chk_appstore_app_sku_attribute_value_type
    CHECK (value_type IN ('string', 'int', 'decimal', 'bool', 'json', 'enum', 'ref')),
  CONSTRAINT chk_appstore_app_sku_attribute_sort_weight CHECK (sort_weight >= 0)
);

-- `locale` is NOT NULL with an empty-string sentinel rather than nullable: a
-- nullable column would not participate in the uniqueness boundary, because
-- PostgreSQL treats `NULL <> NULL`, and duplicate non-localized attributes
-- would become insertable.
CREATE UNIQUE INDEX IF NOT EXISTS uq_appstore_app_sku_attribute_key
  ON appstore_app_sku_attribute (tenant_id, app_sku_id, attribute_group, attribute_key, locale)
  WHERE deleted_at IS NULL;

CREATE INDEX IF NOT EXISTS idx_appstore_app_sku_attribute_sku
  ON appstore_app_sku_attribute (tenant_id, app_sku_id, attribute_group, sort_weight, id);

-- ---------------------------------------------------------------------------
-- Part 3 — Specification model bindings (which models implement a SKU)
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS appstore_app_sku_model (
  id BIGINT NOT NULL PRIMARY KEY,
  uuid VARCHAR(64) NOT NULL,
  tenant_id BIGINT NOT NULL,
  organization_id BIGINT NOT NULL DEFAULT 0,
  app_sku_id BIGINT NOT NULL,
  model_key VARCHAR(128) NOT NULL,
  model_provider VARCHAR(64),
  implementation_role VARCHAR(32) NOT NULL DEFAULT 'primary',
  implementation_scope VARCHAR(64),
  weight INTEGER NOT NULL DEFAULT 100,
  enabled BOOLEAN NOT NULL DEFAULT TRUE,
  config_snapshot JSONB NOT NULL DEFAULT '{}'::jsonb,
  metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
  status INTEGER NOT NULL DEFAULT 1,
  version BIGINT NOT NULL DEFAULT 0,
  deleted_at TIMESTAMPTZ,
  created_by BIGINT,
  updated_by BIGINT,
  deleted_by BIGINT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT uk_appstore_app_sku_model_uuid UNIQUE (uuid),
  CONSTRAINT chk_appstore_app_sku_model_role
    CHECK (implementation_role IN ('primary', 'assistant', 'reviewer', 'fallback')),
  CONSTRAINT chk_appstore_app_sku_model_weight CHECK (weight >= 0)
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_appstore_app_sku_model_binding
  ON appstore_app_sku_model (tenant_id, app_sku_id, model_key, implementation_role)
  WHERE deleted_at IS NULL;

CREATE INDEX IF NOT EXISTS idx_appstore_app_sku_model_sku
  ON appstore_app_sku_model (tenant_id, app_sku_id, enabled, implementation_role, id);

-- Reverse lookup: which specifications a model implements. Feeds model coverage
-- and deprecation impact analysis.
CREATE INDEX IF NOT EXISTS idx_appstore_app_sku_model_model
  ON appstore_app_sku_model (tenant_id, model_provider, model_key);

-- ---------------------------------------------------------------------------
-- Part 4 — Specification contributors (concurrent authorship attribution)
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS appstore_app_sku_contributor (
  id BIGINT NOT NULL PRIMARY KEY,
  uuid VARCHAR(64) NOT NULL,
  tenant_id BIGINT NOT NULL,
  organization_id BIGINT NOT NULL DEFAULT 0,
  app_sku_id BIGINT NOT NULL,
  user_id BIGINT NOT NULL,
  contributor_role VARCHAR(32) NOT NULL DEFAULT 'developer',
  contribution_share INTEGER,
  joined_at TIMESTAMPTZ,
  left_at TIMESTAMPTZ,
  metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
  status INTEGER NOT NULL DEFAULT 1,
  version BIGINT NOT NULL DEFAULT 0,
  deleted_at TIMESTAMPTZ,
  created_by BIGINT,
  updated_by BIGINT,
  deleted_by BIGINT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT uk_appstore_app_sku_contributor_uuid UNIQUE (uuid),
  CONSTRAINT chk_appstore_app_sku_contributor_role
    CHECK (contributor_role IN ('owner', 'developer', 'reviewer', 'publisher')),
  CONSTRAINT chk_appstore_app_sku_contributor_share
    CHECK (contribution_share IS NULL OR (contribution_share >= 0 AND contribution_share <= 100)),
  CONSTRAINT chk_appstore_app_sku_contributor_period
    CHECK (left_at IS NULL OR joined_at IS NULL OR left_at >= joined_at)
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_appstore_app_sku_contributor_member
  ON appstore_app_sku_contributor (tenant_id, app_sku_id, user_id, contributor_role)
  WHERE deleted_at IS NULL;

CREATE INDEX IF NOT EXISTS idx_appstore_app_sku_contributor_sku
  ON appstore_app_sku_contributor (tenant_id, app_sku_id, contributor_role, id);

-- Subject-scope index for "which specifications does this user contribute to".
CREATE INDEX IF NOT EXISTS idx_appstore_app_sku_contributor_user
  ON appstore_app_sku_contributor (tenant_id, user_id, contributor_role, app_sku_id);

-- ---------------------------------------------------------------------------
-- Part 5 — Deployment bindings (appstore app/SKU to owned deployments)
-- ---------------------------------------------------------------------------

CREATE TABLE IF NOT EXISTS appstore_app_deployment_binding (
  id BIGINT NOT NULL PRIMARY KEY,
  uuid VARCHAR(64) NOT NULL,
  tenant_id BIGINT NOT NULL,
  organization_id BIGINT NOT NULL DEFAULT 0,
  app_id TEXT NOT NULL,
  app_sku_id BIGINT,
  deploy_app_id BIGINT NOT NULL,
  deploy_app_uuid VARCHAR(36),
  deploy_deployment_id BIGINT,
  deploy_deployment_uuid VARCHAR(64),
  environment VARCHAR(16) NOT NULL DEFAULT 'production',
  platform_code VARCHAR(64) NOT NULL DEFAULT '',
  binding_role VARCHAR(24) NOT NULL DEFAULT 'primary',
  binding_status VARCHAR(24) NOT NULL DEFAULT 'pending',
  is_default BOOLEAN NOT NULL DEFAULT FALSE,
  config_snapshot JSONB NOT NULL DEFAULT '{}'::jsonb,
  sync_status VARCHAR(24),
  last_synced_at TIMESTAMPTZ,
  metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
  status INTEGER NOT NULL DEFAULT 1,
  version BIGINT NOT NULL DEFAULT 0,
  deleted_at TIMESTAMPTZ,
  created_by BIGINT,
  updated_by BIGINT,
  deleted_by BIGINT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT uk_appstore_app_deployment_binding_uuid UNIQUE (uuid),
  CONSTRAINT chk_appstore_app_deployment_binding_environment
    CHECK (environment IN ('development', 'test', 'staging', 'demo', 'production')),
  CONSTRAINT chk_appstore_app_deployment_binding_role
    CHECK (binding_role IN ('primary', 'canary', 'backup', 'shadow')),
  CONSTRAINT chk_appstore_app_deployment_binding_status
    CHECK (binding_status IN ('pending', 'active', 'degraded', 'invalid', 'revoked')),
  CONSTRAINT chk_appstore_app_deployment_binding_sync_status
    CHECK (sync_status IS NULL OR sync_status IN ('synced', 'stale', 'unknown', 'error'))
);

-- One binding per application, deployment target, environment and platform.
-- `platform_code` is NOT NULL with an empty-string sentinel for the same reason
-- as `locale` above.
CREATE UNIQUE INDEX IF NOT EXISTS uq_appstore_app_deployment_binding_target
  ON appstore_app_deployment_binding (tenant_id, app_id, deploy_app_id, environment, platform_code)
  WHERE deleted_at IS NULL;

-- One default deployment surface per application and environment, so each
-- lifecycle environment has its own resolvable default.
CREATE UNIQUE INDEX IF NOT EXISTS uq_appstore_app_deployment_binding_default
  ON appstore_app_deployment_binding (tenant_id, app_id, environment)
  WHERE is_default AND deleted_at IS NULL;

CREATE INDEX IF NOT EXISTS idx_appstore_app_deployment_binding_app
  ON appstore_app_deployment_binding (tenant_id, app_id, environment, binding_status, id);

-- Nullable column, so the SKU-level lookup index is partial.
CREATE INDEX IF NOT EXISTS idx_appstore_app_deployment_binding_sku
  ON appstore_app_deployment_binding (tenant_id, app_sku_id)
  WHERE app_sku_id IS NOT NULL;

-- Reverse lookup from the deployment side: which appstore applications bind a
-- given `deploy_app`. Cross-module integrity is verified through the
-- deployments SDK, so this index backs repair and reconciliation jobs.
CREATE INDEX IF NOT EXISTS idx_appstore_app_deployment_binding_deploy_app
  ON appstore_app_deployment_binding (tenant_id, deploy_app_id, environment);

CREATE INDEX IF NOT EXISTS idx_appstore_app_deployment_binding_deploy_deployment
  ON appstore_app_deployment_binding (tenant_id, deploy_deployment_id)
  WHERE deploy_deployment_id IS NOT NULL;

-- ---------------------------------------------------------------------------
-- Part 6 — Attach the new layer to the existing application and release rows
-- ---------------------------------------------------------------------------

ALTER TABLE appstore_app
  ADD COLUMN IF NOT EXISTS default_sku_id BIGINT,
  ADD COLUMN IF NOT EXISTS default_deployment_binding_id BIGINT;

-- Published artifacts attach to the specification they ship. Nullable so the
-- existing rows stay valid while releases are migrated onto specifications.
ALTER TABLE appstore_release
  ADD COLUMN IF NOT EXISTS app_sku_id BIGINT;

CREATE INDEX IF NOT EXISTS idx_appstore_release_app_sku
  ON appstore_release (tenant_id, app_sku_id)
  WHERE app_sku_id IS NOT NULL;

ALTER TABLE appstore_platform_release
  ADD COLUMN IF NOT EXISTS app_sku_id BIGINT;

CREATE INDEX IF NOT EXISTS idx_appstore_platform_release_app_sku
  ON appstore_platform_release (tenant_id, app_sku_id)
  WHERE app_sku_id IS NOT NULL;

COMMIT;

