--   template_platform, no data is dropped)
-- transactional: true
-- lock: lightweight
-- lock_timeout: 2s
-- statement_timeout: 60s

ALTER TABLE appstore_app_template
  ADD COLUMN IF NOT EXISTS template_platform VARCHAR(64);

CREATE INDEX IF NOT EXISTS idx_appstore_app_template_platform
  ON appstore_app_template (tenant_id, organization_id, template_platform, publish_status, id);

-- folded migration: migrations/postgres/0007_application_identity_renames.up.sql
-- sdkwork:migration
-- id: 0007_application_identity_renames
-- engine: postgres
-- module: sdkwork-appstore
-- purpose: Phase 2 of the application-factory restructure
--   (APPLICATION_FACTORY_DB_RESTRUCTURE_PLAN.md). The catalog app, its
--   listings, and its releases become application-scoped names so the
--   product identity reads the same in every module, the SKU provenance
--   points at the deploy scaffold instead of a store-local template, and a
--   listing price can be resolved per application.
--   Renames only: no row is rewritten and no column is dropped.
-- reversible: true
-- rollback: down-migration (every statement is a rename or an additive
--   nullable column; the paired down migration reverses it)
-- transactional: true
-- lock: ACCESS EXCLUSIVE on the renamed tables and indexes
-- lock_timeout: 2s
-- statement_timeout: 60s

BEGIN;

-- Tables
ALTER TABLE appstore_app RENAME TO appstore_application;
ALTER TABLE appstore_app_dependency RENAME TO appstore_application_dependency;
ALTER TABLE appstore_app_deployment_binding RENAME TO appstore_application_deployment_binding;
ALTER TABLE appstore_app_platform RENAME TO appstore_application_platform;
ALTER TABLE appstore_app_sku RENAME TO appstore_application_sku;
ALTER TABLE appstore_app_sku_attribute RENAME TO appstore_application_sku_attribute;
ALTER TABLE appstore_app_sku_contributor RENAME TO appstore_application_sku_contributor;
ALTER TABLE appstore_app_sku_model RENAME TO appstore_application_sku_model;
ALTER TABLE appstore_listing RENAME TO appstore_application_listing;
ALTER TABLE appstore_listing_category_binding RENAME TO appstore_application_listing_category_binding;
ALTER TABLE appstore_listing_iap_item RENAME TO appstore_application_listing_iap_item;
ALTER TABLE appstore_listing_localization RENAME TO appstore_application_listing_localization;
ALTER TABLE appstore_listing_media RENAME TO appstore_application_listing_media;
ALTER TABLE appstore_listing_metric_snapshot RENAME TO appstore_application_listing_metric_snapshot;
ALTER TABLE appstore_listing_price RENAME TO appstore_application_listing_price;
ALTER TABLE appstore_listing_rating RENAME TO appstore_application_listing_rating;
ALTER TABLE appstore_listing_review RENAME TO appstore_application_listing_review;
ALTER TABLE appstore_listing_review_report RENAME TO appstore_application_listing_review_report;
ALTER TABLE appstore_listing_review_vote RENAME TO appstore_application_listing_review_vote;
ALTER TABLE appstore_listing_submission RENAME TO appstore_application_listing_submission;
ALTER TABLE appstore_listing_tag_binding RENAME TO appstore_application_listing_tag_binding;
ALTER TABLE appstore_platform_release RENAME TO appstore_application_platform_release;
ALTER TABLE appstore_release RENAME TO appstore_application_release;
ALTER TABLE appstore_release_artifact RENAME TO appstore_application_release_artifact;
ALTER TABLE appstore_release_beta_invite RENAME TO appstore_application_release_beta_invite;
ALTER TABLE appstore_release_channel RENAME TO appstore_application_release_channel;
ALTER TABLE appstore_release_note_localization RENAME TO appstore_application_release_note_localization;
ALTER TABLE appstore_release_rollout RENAME TO appstore_application_release_rollout;
ALTER TABLE appstore_release_tester_group RENAME TO appstore_application_release_tester_group;
ALTER TABLE appstore_release_tester_group_member RENAME TO appstore_application_release_tester_group_member;

-- Indexes (unique indexes also move from uq_ to the standard uk_ prefix)
ALTER INDEX idx_appstore_app_deployment_binding_app RENAME TO idx_appstore_application_deployment_binding_app;
ALTER INDEX idx_appstore_app_deployment_binding_deploy_app RENAME TO idx_appstore_application_deployment_binding_deploy_app;
ALTER INDEX idx_appstore_app_deployment_binding_deploy_deployment RENAME TO idx_appstore_application_deployment_binding_deploy_deployment;
ALTER INDEX idx_appstore_app_deployment_binding_sku RENAME TO idx_appstore_application_deployment_binding_sku;
ALTER INDEX idx_appstore_app_platform_app RENAME TO idx_appstore_application_platform_app;
ALTER INDEX idx_appstore_app_sku_attribute_sku RENAME TO idx_appstore_application_sku_attribute_sku;
ALTER INDEX idx_appstore_app_sku_contributor_sku RENAME TO idx_appstore_application_sku_contributor_sku;
ALTER INDEX idx_appstore_app_sku_contributor_user RENAME TO idx_appstore_application_sku_contributor_user;
ALTER INDEX idx_appstore_app_sku_list RENAME TO idx_appstore_application_sku_list;
ALTER INDEX idx_appstore_app_sku_model_model RENAME TO idx_appstore_application_sku_model_model;
ALTER INDEX idx_appstore_app_sku_model_sku RENAME TO idx_appstore_application_sku_model_sku;
ALTER INDEX idx_appstore_app_sku_owner RENAME TO idx_appstore_application_sku_owner;
ALTER INDEX idx_appstore_app_sku_provenance RENAME TO idx_appstore_application_sku_provenance;
ALTER INDEX idx_appstore_app_sku_version RENAME TO idx_appstore_application_sku_version;
ALTER INDEX idx_appstore_app_status RENAME TO idx_appstore_application_status;
ALTER INDEX idx_appstore_listing_catalog RENAME TO idx_appstore_application_listing_catalog;
ALTER INDEX idx_appstore_listing_iap_item_listing RENAME TO idx_appstore_application_listing_iap_item_listing;
ALTER INDEX idx_appstore_listing_price_lookup RENAME TO idx_appstore_application_listing_price_lookup;
ALTER INDEX idx_appstore_listing_publisher RENAME TO idx_appstore_application_listing_publisher;
ALTER INDEX idx_appstore_listing_rating_listing RENAME TO idx_appstore_application_listing_rating_listing;
ALTER INDEX idx_appstore_listing_review_listing RENAME TO idx_appstore_application_listing_review_listing;
