-- folded migration: migrations/postgres/0008_application_version_identity_slice.up.sql
-- sdkwork:migration
-- id: 0008_application_version_identity_slice
-- engine: postgres
-- module: sdkwork-appstore
-- purpose: Phase 3 of the application-factory restructure
--   (APPLICATION_FACTORY_DB_RESTRUCTURE_PLAN.md). Introduce the product version
--   as the single owner of the identity slice that IAM's application template
--   used to hold (app key, package/bundle identity, app type, default access
--   permissions, runtime relying-party config, manifest hash).
--
--   The release rows stay listing-scoped; `appstore_application_release.version_id`
--   lets a release point at the product version it ships, so the identity slice
--   is authored once per product version instead of once per storefront listing.
--   Both statements are additive.
-- reversible: true
-- rollback: down-migration (the added column is nullable and the new table is
--   additive; the paired down migration drops them)
-- transactional: true
-- lock: lightweight (new table and nullable column only)
-- lock_timeout: 2s
-- statement_timeout: 60s

BEGIN;

CREATE TABLE IF NOT EXISTS appstore_application_version (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  organization_id TEXT NOT NULL DEFAULT '0',
  application_id TEXT NOT NULL,
  -- Identity slice formerly owned by the IAM application template.
  app_key TEXT NOT NULL,
  app_type TEXT NOT NULL,
  package_name TEXT,
  bundle_id TEXT,
  desktop_app_id TEXT,
  default_access_permissions_json TEXT NOT NULL DEFAULT '[]',
  runtime_config_json TEXT NOT NULL DEFAULT '{}',
  manifest_hash TEXT,
  -- Version attributes.
  version_name TEXT NOT NULL,
  version_code TEXT NOT NULL,
  channel_code TEXT NOT NULL DEFAULT 'stable',
  version_status TEXT NOT NULL DEFAULT 'draft',
  published_at TIMESTAMPTZ,
  retired_at TIMESTAMPTZ,
  version INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, application_id, version_code),
  CONSTRAINT chk_appstore_application_version_status
    CHECK (version_status IN ('draft', 'pending_review', 'approved', 'published', 'deprecated', 'retired'))
);

CREATE UNIQUE INDEX IF NOT EXISTS uk_appstore_application_version_app_key
  ON appstore_application_version (tenant_id, app_key);

CREATE INDEX IF NOT EXISTS idx_appstore_application_version_list
  ON appstore_application_version (tenant_id, application_id, version_status, version_code DESC, id);

ALTER TABLE appstore_application_release
  ADD COLUMN IF NOT EXISTS version_id TEXT;

CREATE INDEX IF NOT EXISTS idx_appstore_application_release_version
  ON appstore_application_release (tenant_id, version_id);

COMMIT;

-- folded migration: migrations/postgres/0009_expert_catalog.up.sql
-- sdkwork:migration
-- id: 0009_expert_catalog
-- engine: postgres
-- module: sdkwork-appstore
-- purpose: Phase 4 prerequisite of the application-factory restructure
--   (APPLICATION_FACTORY_READINESS_GAP_REPORT.md R4). The AI expert catalog was
--   stored inside appstore_app_template with template_type = 'EXPERT', which is
--   how a presentation catalog ended up owning the scaffold table. This table
--   gives the catalog its own store so the template family can be retired
--   without losing the experts page.
--
--   Additive only: the existing rows stay in the template table until the data
--   migration copies them, so no reader breaks in between.
-- reversible: true
-- rollback: down-migration (the table is additive; the paired down migration
--   drops it)
-- transactional: true
-- lock: lightweight (new table only)
-- lock_timeout: 2s
-- statement_timeout: 60s

BEGIN;

CREATE TABLE IF NOT EXISTS appstore_expert_catalog (
  id TEXT PRIMARY KEY,
  tenant_id TEXT NOT NULL,
  organization_id TEXT NOT NULL DEFAULT '0',
  expert_code TEXT NOT NULL,
  expert_name TEXT NOT NULL,
  description TEXT,
  category_code TEXT,
  -- Presentation payload that the storefront renders: nickname, tags, prompts,
  -- avatar, popularity, rating, badge, and usage counters.
  profile_json TEXT NOT NULL DEFAULT '{}',
  expert_status TEXT NOT NULL DEFAULT 'draft',
  visibility INTEGER NOT NULL DEFAULT 0,
  featured BOOLEAN NOT NULL DEFAULT FALSE,
  sort_weight INTEGER NOT NULL DEFAULT 0,
  owner_user_id TEXT,
  version BIGINT NOT NULL DEFAULT 0,
  published_at TIMESTAMPTZ,
  deleted_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT chk_appstore_expert_catalog_status
    CHECK (expert_status IN ('draft', 'published', 'hidden', 'retired'))
);

CREATE UNIQUE INDEX IF NOT EXISTS uk_appstore_expert_catalog_code
  ON appstore_expert_catalog (tenant_id, expert_code)
  WHERE deleted_at IS NULL;

CREATE INDEX IF NOT EXISTS idx_appstore_expert_catalog_listing
  ON appstore_expert_catalog (tenant_id, category_code, sort_weight, id)
  WHERE deleted_at IS NULL;

COMMIT;

-- folded migration: migrations/postgres/0010_expert_catalog_backfill.up.sql
-- sdkwork:migration
-- id: 0010_expert_catalog_backfill
-- engine: postgres
-- module: sdkwork-appstore
-- purpose: Phase R4 data step of the application-factory restructure. Copy the
--   expert catalog out of appstore_app_template (template_type = 'EXPERT') into
--   its own table so the template family can be retired without losing the
--   experts page.
--
--   Idempotent: rows already present are left untouched, so a replay or a
--   partially applied database converges. The paired seed writes the same rows
--   for a fresh install; this migration covers databases that were seeded
--   before the table existed.
-- reversible: false
-- rollback: forward-fix (a copy of presentation rows; replaying is a no-op)
-- transactional: true
-- lock: shared on appstore_app_template, row inserts on appstore_expert_catalog
-- lock_timeout: 2s
-- statement_timeout: 60s

BEGIN;

INSERT INTO appstore_expert_catalog (
    id, tenant_id, organization_id, expert_code, expert_name, description, category_code,
    profile_json, expert_status, visibility, featured, sort_weight, owner_user_id, version,
    published_at, created_at, updated_at
)
SELECT
    t.id::text,
    t.tenant_id::text,
    t.organization_id::text,
    t.template_code,
    COALESCE(t.template_name, t.template_code),
    t.description,
    t.category_code,
    COALESCE(t.metadata::text, '{}'),
    CASE WHEN t.publish_status = 1 THEN 'published' ELSE 'draft' END,
    COALESCE(t.visibility, 0),
    COALESCE(t.featured, FALSE),
    COALESCE(t.sort_weight, 0),
    CASE WHEN t.owner_user_id IS NULL THEN NULL ELSE t.owner_user_id::text END,
    COALESCE(t.version, 0),
    CASE WHEN t.publish_status = 1 THEN t.updated_at END,
    t.created_at,
    t.updated_at
FROM appstore_app_template t
WHERE t.template_type = 'EXPERT'
  AND t.template_code IS NOT NULL
  AND t.deleted_at IS NULL
ON CONFLICT DO NOTHING;

COMMIT;

-- folded migration: migrations/postgres/0011_retire_app_template_family.up.sql
-- sdkwork:migration
-- id: 0011_retire_app_template_family
-- engine: postgres
-- module: sdkwork-appstore
-- purpose: Retire the application-template family from the appstore schema.
--
--   `appstore_app_template`, `appstore_app_template_version` and
--   `appstore_app_template_usage` were the leftover scaffold shelf of the
--   storefront. Application scaffolds are owned by the deploy service
--   (`/app/v3/api/app_templates`), and the curated AI expert roster that used to
--   ride the shelf as `template_type = 'EXPERT'` now lives in its own
--   `appstore_expert_catalog` table (migration 0009, backfilled by migration
--   0010 and by the `014_expert_catalog.sql` seed). Nothing reads or writes the
--   template tables any more, so they are dropped instead of kept as a
--   compatibility surface.
--
--   The baseline (`0001_appstore_baseline.sql`) keeps its historical CREATE
--   statements: a baseline is an immutable snapshot, and the retirement is
--   expressed forward, at the end of the migration chain, so replaying the chain
--   reaches the 73-table live schema.
--
--   `DROP TABLE` without `CASCADE` is deliberate: the three tables reference each
--   other and nothing else references them. If a database still carries an
--   unexpected dependent object, this migration must fail loudly instead of
--   silently dropping it.
-- reversible: false
-- rollback: forward-fix (dropped tables and their rows are not recoverable; a
--   restore re-creates them from a backup taken before this migration)
-- transactional: true
-- lock: exclusive on appstore_app_template_usage, appstore_app_template_version,
--   appstore_app_template
-- lock_timeout: 2s
-- statement_timeout: 60s

BEGIN;

DROP TABLE IF EXISTS appstore_app_template_usage;
DROP TABLE IF EXISTS appstore_app_template_version;
DROP TABLE IF EXISTS appstore_app_template;

COMMIT;
